            payload = {"event_type": "channel_reject", "client_payload": {"username": username, "decision": "reject"}}
            response = HTTP.post(url, headers={"Accept": "application/vnd.github+json", "Authorization": "Bearer " + GITHUB_TOKEN, "X-GitHub-Api-Version": "2022-11-28"}, json=payload)
            if response.status_code == 204:
                bot.sendMessage("Rejection request submitted for @" + username + ". The candidate will remain in the registry as rejected and will not be activated.")
            else:
                bot.sendMessage("GitHub rejected the request. Check token permissions. HTTP " + str(response.status_code))
        except Exception:
            bot.sendMessage("Could not submit rejection. Check GITHUB_TOKEN permissions and TBC HTTP support.")
else:
    bot.sendMessage("Access denied.")

if str(u) in [str(x) for x in OWNER_IDS] and message.chat.type == "private":
    try:
        parts = str(params or "").strip().split()
        if len(parts) > 1:
            bot.sendMessage("Usage: /summary [YYYY-MM-DD]")
        else:
            report_date = parts[0] if parts else ""
            if not report_date:
                latest = HTTP.get(FEED_URL)
                if latest.status_code != 200:
                    bot.sendMessage("Could not determine the latest reporting date. Try /summary YYYY-MM-DD.")
                    report_date = ""
                else:
                    latest_data = latest.json()
                    report_date = str(latest_data.get("summary", {}).get("report_date", "")).strip()
            if report_date:
                if len(report_date) != 10 or report_date[4:5] != "-" or report_date[7:8] != "-":
                    bot.sendMessage("Invalid date. Use YYYY-MM-DD.")
                else:
                    url = "https://raw.githubusercontent.com/fyroz118/Legion-OSINT/main/docs/feed/archive/" + report_date + "/intelligence_report.json"
                    response = HTTP.get(url)
                    if response.status_code != 200:
                        bot.sendMessage("The expanded intelligence report is not available for " + report_date + ". It is generated by the next successful collection/publisher run; older dates are not automatically backfilled.")
                    else:
                        report = response.json()
                        executive = report.get("executive_assessment", {})
                        lines = [
                            str(report.get("title", "LEGION-OSINT DAILY INTELLIGENCE REPORT")),
                            "Reporting date: " + str(report.get("report_date", report_date)) + " | Timezone: " + str(report.get("timezone", "Asia/Dhaka")),
                            "Generated: " + str(report.get("generated_at", "unknown")),
                            "Classification: " + str(report.get("classification", "OSINT source-lead digest")),
                            "",
                            "EXECUTIVE COLLECTION PICTURE",
                            "Source posts/articles: " + str(executive.get("source_posts_in_daily_archive", 0)) + " | Telegram: " + str(executive.get("telegram_posts", 0)) + " | RSS: " + str(executive.get("rss_articles", 0)),
                            "Regions represented: " + str(executive.get("regions_represented", 0)),
                            str(executive.get("key_caveat", "")),
                            ""
                        ]
                        for section in report.get("report_sections", []):
                            lines.append(str(section.get("heading", "")))
                            lines.append(str(section.get("text", "")))
                            if section.get("topic_buckets"):
                                for bucket in section.get("topic_buckets", []):
                                    lines.append("- " + str(bucket.get("section", "")) + ": " + str(bucket.get("matching_source_posts", 0)) + " matching posts (keyword indicator only)")
                            if section.get("watch_indicators"):
                                for indicator in section.get("watch_indicators", []):
                                    lines.append("- " + str(indicator))
                            lines.append("")
                        lines.append("SOURCE REPORTS — UNVERIFIED LEADS")
                        records = report.get("source_records", [])
                        for index, item in enumerate(records):
                            publisher = item.get("publisher_name") or item.get("channel_username") or "unknown source"
                            body = " ".join(str(item.get("text", "")).split())[:650]
                            lines.append("\n[" + str(index + 1) + "] " + str(publisher) + " | " + str(item.get("platform", "unknown")) + " | " + str(item.get("published_at") or "publication time unknown"))
                            lines.append("Region: " + str(item.get("priority_region", "unknown")) + " | Class: " + str(item.get("source_class", "unknown")) + " | Status: UNVERIFIED")
                            lines.append(body)
                            lines.append(str(item.get("source_url", "")))
                        lines.append("\nSOURCE INTEGRITY NOTICE")
                        lines.append(str(report.get("notice", "All records are unverified source leads. Verify original sources; reposts are not independent corroboration.")))
                        full_text = "\n".join(lines)
                        chunks = []
                        while len(full_text) > 3500:
                            cut = full_text.rfind("\n", 0, 3500)
                            if cut < 1000:
                                cut = 3500
                            chunks.append(full_text[:cut])
                            full_text = full_text[cut:].lstrip()
                        if full_text:
                            chunks.append(full_text)
                        for chunk in chunks:
                            bot.sendMessage(chunk, disable_web_page_preview=True)
    except Exception:
        bot.sendMessage("Could not retrieve or format the expanded daily intelligence report. Check that the collection workflow has generated the report for this date.")
else:
    bot.sendMessage("Access denied. Legion-OSINT is restricted to its owner in private chat.")
